algorithms.pseudocode:
CHECK_MIN_DOMINANCE(f, g, test_points):
  for x in test_points:
    v1 := T1.inv_vec(x)
    v2 := T2.inv_vec(f(x))
    v3 := T3.inv_vec(g(f(x)))
    m := min(v1, v2)  // coordinatewise
    if any(v3[i] > m[i]):
      return FAIL(x, i)
  return SUCCESS

Time: O(|test_points| * k)
